79     struct AudioStatistics
80     {
81         size_t  playingOneShots;        // Number of one-shot sounds currently playing
82         size_t  playingInstances;       // Number of sound effect instances currently playing
83         size_t  allocatedInstances;     // Number of SoundEffectInstance allocated
84         size_t  allocatedVoices;        // Number of XAudio2 voices allocated (standard, 3D, one-shots, and idle one-shots)
85         size_t  allocatedVoices3d;      // Number of XAudio2 voices allocated for 3D
86         size_t  allocatedVoicesOneShot; // Number of XAudio2 voices allocated for one-shot sounds
87         size_t  allocatedVoicesIdle;    // Number of XAudio2 voices allocated for one-shot sounds but not currently in use
88         size_t  audioBytes;             // Total wave data (in bytes) in SoundEffects and in-memory WaveBanks
89     #if (defined(_XBOX_ONE) && defined(_TITLE)) || defined(_GAMING_XBOX)
90         size_t  xmaAudioBytes;          // Total wave data (in bytes) in SoundEffects and in-memory WaveBanks allocated with ApuAlloc
91     #endif
92         size_t  streamingBytes;         // Total size of streaming buffers (in bytes) in streaming WaveBanks
93     };
