97     class IVoiceNotify
98     {
99     public:
100         virtual ~IVoiceNotify() = default;
101 
102         IVoiceNotify(const IVoiceNotify&) = delete;
103         IVoiceNotify& operator=(const IVoiceNotify&) = delete;
104 
105         IVoiceNotify(IVoiceNotify&&) = default;
106         IVoiceNotify& operator=(IVoiceNotify&&) = default;
107 
108         virtual void __cdecl OnBufferEnd() = 0;
109             // Notfication that a voice buffer has finished
110             // Note this is called from XAudio2's worker thread, so it should perform very minimal and thread-safe operations
111 
112         virtual void __cdecl OnCriticalError() = 0;
113             // Notification that the audio engine encountered a critical error
114 
115         virtual void __cdecl OnReset() = 0;
116             // Notification of an audio engine reset
117 
118         virtual void __cdecl OnUpdate() = 0;
119             // Notification of an audio engine per-frame update (opt-in)
120 
121         virtual void __cdecl OnDestroyEngine() noexcept = 0;
122             // Notification that the audio engine is being destroyed
123 
124         virtual void __cdecl OnTrim() = 0;
125             // Notification of a request to trim the voice pool
126 
127         virtual void __cdecl GatherStatistics(AudioStatistics& stats) const = 0;
128             // Contribute to statistics request
129 
130         virtual void __cdecl OnDestroyParent() noexcept = 0;
131             // Optional notification used by some objects
132 
133     protected:
134         IVoiceNotify() = default;
135     };
