207     class AudioEngine
208     {
209     public:
210         explicit AudioEngine(
211             AUDIO_ENGINE_FLAGS flags = AudioEngine_Default,
212             _In_opt_ const WAVEFORMATEX* wfx = nullptr,
213             _In_opt_z_ const wchar_t* deviceId = nullptr,
214             AUDIO_STREAM_CATEGORY category = AudioCategory_GameEffects) noexcept(false);
215 
216         AudioEngine(AudioEngine&&) noexcept;
217         AudioEngine& operator= (AudioEngine&&) noexcept;
218 
219         AudioEngine(AudioEngine const&) = delete;
220         AudioEngine& operator= (AudioEngine const&) = delete;
221 
222         virtual ~AudioEngine();
223 
224         bool __cdecl Update();
225             // Performs per-frame processing for the audio engine, returns false if in 'silent mode'
226 
227         bool __cdecl Reset(_In_opt_ const WAVEFORMATEX* wfx = nullptr, _In_opt_z_ const wchar_t* deviceId = nullptr);
228             // Reset audio engine from critical error/silent mode using a new device; can also 'migrate' the graph
229             // Returns true if succesfully reset, false if in 'silent mode' due to no default device
230             // Note: One shots are lost, all SoundEffectInstances are in the STOPPED state after successful reset
231 
232         void __cdecl Suspend() noexcept;
233         void __cdecl Resume();
234             // Suspend/resumes audio processing (i.e. global pause/resume)
235 
236         float __cdecl GetMasterVolume() const noexcept;
237         void __cdecl SetMasterVolume(float volume);
238             // Master volume property for all sounds
239 
240         void __cdecl SetReverb(AUDIO_ENGINE_REVERB reverb);
241         void __cdecl SetReverb(_In_opt_ const XAUDIO2FX_REVERB_PARAMETERS* native);
242             // Sets environmental reverb for 3D positional audio (if active)
243 
244         void __cdecl SetMasteringLimit(int release, int loudness);
245             // Sets the mastering volume limiter properties (if active)
246 
247         AudioStatistics __cdecl GetStatistics() const;
248             // Gathers audio engine statistics
249 
250         WAVEFORMATEXTENSIBLE __cdecl GetOutputFormat() const noexcept;
251             // Returns the format of the audio output device associated with the mastering voice.
252 
253         uint32_t __cdecl GetChannelMask() const noexcept;
254             // Returns the output channel mask
255 
256         int __cdecl GetOutputSampleRate() const noexcept;
257             // Returns the sample rate going into the mastering voice
258 
259         unsigned int __cdecl GetOutputChannels() const noexcept;
260             // Returns the number of channels going into the mastering voice
261 
262         bool __cdecl IsAudioDevicePresent() const noexcept;
263             // Returns true if the audio graph is operating normally, false if in 'silent mode'
264 
265         bool __cdecl IsCriticalError() const noexcept;
266             // Returns true if the audio graph is halted due to a critical error (which also places the engine into 'silent mode')
267 
268         // Voice pool management.
269         void __cdecl SetDefaultSampleRate(int sampleRate);
270             // Sample rate for voices in the reuse pool (defaults to 44100)
271 
272         void __cdecl SetMaxVoicePool(size_t maxOneShots, size_t maxInstances);
273             // Maximum number of voices to allocate for one-shots and instances
274             // Note: one-shots over this limit are ignored; too many instance voices throws an exception
275 
276         void __cdecl TrimVoicePool();
277             // Releases any currently unused voices
278 
279         // Internal-use functions
280         void __cdecl AllocateVoice(_In_ const WAVEFORMATEX* wfx,
281             SOUND_EFFECT_INSTANCE_FLAGS flags, bool oneshot, _Outptr_result_maybenull_ IXAudio2SourceVoice** voice);
282 
283         void __cdecl DestroyVoice(_In_ IXAudio2SourceVoice* voice) noexcept;
284             // Should only be called for instance voices, not one-shots
285 
286         void __cdecl RegisterNotify(_In_ IVoiceNotify* notify, bool usesUpdate);
287         void __cdecl UnregisterNotify(_In_ IVoiceNotify* notify, bool usesOneShots, bool usesUpdate);
288 
289         // XAudio2 interface access
290         IXAudio2* __cdecl GetInterface() const noexcept;
291         IXAudio2MasteringVoice* __cdecl GetMasterVoice() const noexcept;
292         IXAudio2SubmixVoice* __cdecl GetReverbVoice() const noexcept;
293         X3DAUDIO_HANDLE& __cdecl Get3DHandle() const noexcept;
294 
295         // Static functions
296         struct RendererDetail
297         {
298             std::wstring deviceId;
299             std::wstring description;
300         };
301 
302         static std::vector<RendererDetail> __cdecl GetRendererDetails();
303             // Returns a list of valid audio endpoint devices
304 
305 #if defined(_MSC_VER) && !defined(_NATIVE_WCHAR_T_DEFINED)
306         explicit AudioEngine(
307             AUDIO_ENGINE_FLAGS flags = AudioEngine_Default,
308             _In_opt_ const WAVEFORMATEX* wfx = nullptr,
309             _In_opt_z_ const __wchar_t* deviceId = nullptr,
310             AUDIO_STREAM_CATEGORY category = AudioCategory_GameEffects) noexcept(false);
311 
312         bool __cdecl Reset(_In_opt_ const WAVEFORMATEX* wfx = nullptr, _In_opt_z_ const __wchar_t* deviceId = nullptr);
313 #endif
314 
315     private:
316         // Private implementation.
317         class Impl;
318         std::unique_ptr<Impl> pImpl;
319     };
