461     //----------------------------------------------------------------------------------
462     struct AudioListener : public X3DAUDIO_LISTENER
463     {
464         X3DAUDIO_CONE   ListenerCone;
465 
466         AudioListener() noexcept :
467             X3DAUDIO_LISTENER{},
468             ListenerCone{}
469         {
470             OrientFront.z = -1.f;
471 
472             OrientTop.y = 1.f;
473         }
474 
475         void XM_CALLCONV SetPosition(FXMVECTOR v) noexcept
476         {
477             XMStoreFloat3(reinterpret_cast<XMFLOAT3*>(&Position), v);
478         }
479         void __cdecl SetPosition(const XMFLOAT3& pos) noexcept
480         {
481             Position.x = pos.x;
482             Position.y = pos.y;
483             Position.z = pos.z;
484         }
485 
486         void XM_CALLCONV SetVelocity(FXMVECTOR v) noexcept
487         {
488             XMStoreFloat3(reinterpret_cast<XMFLOAT3*>(&Velocity), v);
489         }
490         void __cdecl SetVelocity(const XMFLOAT3& vel) noexcept
491         {
492             Velocity.x = vel.x;
493             Velocity.y = vel.y;
494             Velocity.z = vel.z;
495         }
496 
497         void XM_CALLCONV SetOrientation(FXMVECTOR forward, FXMVECTOR up) noexcept
498         {
499             XMStoreFloat3(reinterpret_cast<XMFLOAT3*>(&OrientFront), forward);
500             XMStoreFloat3(reinterpret_cast<XMFLOAT3*>(&OrientTop), up);
501         }
502         void __cdecl SetOrientation(const XMFLOAT3& forward, const XMFLOAT3& up) noexcept
503         {
504             OrientFront.x = forward.x;  OrientTop.x = up.x;
505             OrientFront.y = forward.y;  OrientTop.y = up.y;
506             OrientFront.z = forward.z;  OrientTop.z = up.z;
507         }
508 
509         void XM_CALLCONV SetOrientationFromQuaternion(FXMVECTOR quat) noexcept
510         {
511             const XMVECTOR forward = XMVector3Rotate(g_XMIdentityR2, quat);
512             XMStoreFloat3(reinterpret_cast<XMFLOAT3*>(&OrientFront), forward);
513 
514             const XMVECTOR up = XMVector3Rotate(g_XMIdentityR1, quat);
515             XMStoreFloat3(reinterpret_cast<XMFLOAT3*>(&OrientTop), up);
516         }
517 
518         // Updates velocity and orientation by tracking changes in position over time.
519         void XM_CALLCONV Update(FXMVECTOR newPos, XMVECTOR upDir, float dt) noexcept
520         {
521             if (dt > 0.f)
522             {
523                 const XMVECTOR lastPos = XMLoadFloat3(reinterpret_cast<const XMFLOAT3*>(&Position));
524 
525                 XMVECTOR vDelta = XMVectorSubtract(newPos, lastPos);
526                 const XMVECTOR vt = XMVectorReplicate(dt);
527                 XMVECTOR v = XMVectorDivide(vDelta, vt);
528                 XMStoreFloat3(reinterpret_cast<XMFLOAT3*>(&Velocity), v);
529 
530                 vDelta = XMVector3Normalize(vDelta);
531                 XMStoreFloat3(reinterpret_cast<XMFLOAT3*>(&OrientFront), vDelta);
532 
533                 v = XMVector3Cross(upDir, vDelta);
534                 v = XMVector3Normalize(v);
535 
536                 v = XMVector3Cross(vDelta, v);
537                 v = XMVector3Normalize(v);
538                 XMStoreFloat3(reinterpret_cast<XMFLOAT3*>(&OrientTop), v);
539 
540                 XMStoreFloat3(reinterpret_cast<XMFLOAT3*>(&Position), newPos);
541             }
542         }
543 
544         void __cdecl SetOmnidirectional() noexcept
545         {
546             pCone = nullptr;
547         }
548 
549         void __cdecl SetCone(const X3DAUDIO_CONE& listenerCone);
550     };
