554     struct AudioEmitter : public X3DAUDIO_EMITTER
555     {
556         X3DAUDIO_CONE   EmitterCone;
557         float           EmitterAzimuths[XAUDIO2_MAX_AUDIO_CHANNELS];
558 
559         AudioEmitter() noexcept :
560             X3DAUDIO_EMITTER{},
561             EmitterCone{},
562             EmitterAzimuths{}
563         {
564             OrientFront.z = -1.f;
565 
566             OrientTop.y =
567                 ChannelRadius =
568                 CurveDistanceScaler =
569                 DopplerScaler = 1.f;
570 
571             ChannelCount = 1;
572             pChannelAzimuths = EmitterAzimuths;
573 
574             InnerRadiusAngle = X3DAUDIO_PI / 4.0f;
575         }
576 
577         void XM_CALLCONV SetPosition(FXMVECTOR v) noexcept
578         {
579             XMStoreFloat3(reinterpret_cast<XMFLOAT3*>(&Position), v);
580         }
581         void __cdecl SetPosition(const XMFLOAT3& pos) noexcept
582         {
583             Position.x = pos.x;
584             Position.y = pos.y;
585             Position.z = pos.z;
586         }
587 
588         void XM_CALLCONV SetVelocity(FXMVECTOR v) noexcept
589         {
590             XMStoreFloat3(reinterpret_cast<XMFLOAT3*>(&Velocity), v);
591         }
592         void __cdecl SetVelocity(const XMFLOAT3& vel) noexcept
593         {
594             Velocity.x = vel.x;
595             Velocity.y = vel.y;
596             Velocity.z = vel.z;
597         }
598 
599         void XM_CALLCONV SetOrientation(FXMVECTOR forward, FXMVECTOR up) noexcept
600         {
601             XMStoreFloat3(reinterpret_cast<XMFLOAT3*>(&OrientFront), forward);
602             XMStoreFloat3(reinterpret_cast<XMFLOAT3*>(&OrientTop), up);
603         }
604         void __cdecl SetOrientation(const XMFLOAT3& forward, const XMFLOAT3& up) noexcept
605         {
606             OrientFront.x = forward.x;  OrientTop.x = up.x;
607             OrientFront.y = forward.y;  OrientTop.y = up.y;
608             OrientFront.z = forward.z;  OrientTop.z = up.z;
609         }
610 
611         void XM_CALLCONV SetOrientationFromQuaternion(FXMVECTOR quat) noexcept
612         {
613             const XMVECTOR forward = XMVector3Rotate(g_XMIdentityR2, quat);
614             XMStoreFloat3(reinterpret_cast<XMFLOAT3*>(&OrientFront), forward);
615 
616             const XMVECTOR up = XMVector3Rotate(g_XMIdentityR1, quat);
617             XMStoreFloat3(reinterpret_cast<XMFLOAT3*>(&OrientTop), up);
618         }
619 
620         // Updates velocity and orientation by tracking changes in position over time.
621         void XM_CALLCONV Update(FXMVECTOR newPos, XMVECTOR upDir, float dt) noexcept
622         {
623             if (dt > 0.f)
624             {
625                 const XMVECTOR lastPos = XMLoadFloat3(reinterpret_cast<const XMFLOAT3*>(&Position));
626 
627                 XMVECTOR vDelta = XMVectorSubtract(newPos, lastPos);
628                 const XMVECTOR vt = XMVectorReplicate(dt);
629                 XMVECTOR v = XMVectorDivide(vDelta, vt);
630                 XMStoreFloat3(reinterpret_cast<XMFLOAT3*>(&Velocity), v);
631 
632                 vDelta = XMVector3Normalize(vDelta);
633                 XMStoreFloat3(reinterpret_cast<XMFLOAT3*>(&OrientFront), vDelta);
634 
635                 v = XMVector3Cross(upDir, vDelta);
636                 v = XMVector3Normalize(v);
637 
638                 v = XMVector3Cross(vDelta, v);
639                 v = XMVector3Normalize(v);
640                 XMStoreFloat3(reinterpret_cast<XMFLOAT3*>(&OrientTop), v);
641 
642                 XMStoreFloat3(reinterpret_cast<XMFLOAT3*>(&Position), newPos);
643             }
644         }
645 
646         void __cdecl SetOmnidirectional() noexcept
647         {
648             pCone = nullptr;
649         }
650 
651         // Only used for single-channel emitters.
652         void __cdecl SetCone(const X3DAUDIO_CONE& emitterCone);
653 
654         // Set multi-channel emitter azimuths based on speaker configuration geometry.
655         void __cdecl EnableDefaultMultiChannel(unsigned int channels, float radius = 1.f);
656 
657         // Set default volume, LFE, LPF, and reverb curves.
658         void __cdecl EnableDefaultCurves() noexcept;
659         void __cdecl EnableLinearCurves() noexcept;
660 
661         void __cdecl EnableInverseSquareCurves() noexcept
662         {
663             pVolumeCurve = nullptr;
664             pLFECurve = nullptr;
665             pLPFDirectCurve = nullptr;
666             pLPFReverbCurve = nullptr;
667             pReverbCurve = nullptr;
668         }
669     };
